import { EmptyOrderError, InvalidOrderTransitionError } from './errors';
import { OrderLine } from './OrderLine';
import { isCancellable, nextFulfilmentState, OrderState } from './OrderState';

export class Order {
  private constructor(
    readonly id: string,
    readonly customerId: string,
    readonly lines: readonly OrderLine[],
    private currentState: OrderState,
    readonly placedAt: Date,
    private lastUpdatedAt: Date,
  ) {}

  static place(id: string, customerId: string, lines: readonly OrderLine[], now: Date): Order {
    if (lines.length === 0) {
      throw new EmptyOrderError();
    }
    return new Order(id, customerId, [...lines], 'placed', now, now);
  }

  get state(): OrderState {
    return this.currentState;
  }

  get updatedAt(): Date {
    return this.lastUpdatedAt;
  }

  /** Moves the order to `target`, which must be the next state in the fulfilment sequence. */
  advanceTo(target: OrderState, now: Date): void {
    const next = nextFulfilmentState(this.currentState);
    if (next !== target) {
      throw new InvalidOrderTransitionError(`Cannot move order ${this.id} from ${this.currentState} to ${target}`);
    }
    this.transition(target, now);
  }

  cancel(now: Date): void {
    if (!isCancellable(this.currentState)) {
      throw new InvalidOrderTransitionError(`Cannot cancel order ${this.id} in state ${this.currentState}`);
    }
    this.transition('cancelled', now);
  }

  private transition(target: OrderState, now: Date): void {
    this.currentState = target;
    this.lastUpdatedAt = now;
  }
}

