export const ORDER_STATES = ['placed', 'paid', 'packed', 'shipped', 'delivered', 'cancelled'] as const;

export type OrderState = (typeof ORDER_STATES)[number];

/** The fulfilment sequence; an order may only advance one step at a time. */
const FULFILMENT_SEQUENCE: readonly OrderState[] = ['placed', 'paid', 'packed', 'shipped', 'delivered'];

const CANCELLABLE_STATES: ReadonlySet<OrderState> = new Set<OrderState>(['placed', 'paid', 'packed']);

export function isOrderState(value: string): value is OrderState {
  return (ORDER_STATES as readonly string[]).includes(value);
}

export function nextFulfilmentState(current: OrderState): OrderState | undefined {
  const index = FULFILMENT_SEQUENCE.indexOf(current);
  return index >= 0 ? FULFILMENT_SEQUENCE[index + 1] : undefined;
}

export function isCancellable(state: OrderState): boolean {
  return CANCELLABLE_STATES.has(state);
}

