import { InsufficientStockError, UnknownProductError } from './errors';
import { OrderLine } from './OrderLine';
import { Product } from './Product';
import { ProductRepository } from './ProductRepository';
import { Quantity } from './Quantity';

interface Allocation {
  product: Product;
  quantity: Quantity;
}

/**
 * Applies stock movements for a set of order lines all-or-nothing:
 * every line is validated before any product is changed.
 */
export class StockReservationService {
  constructor(private readonly products: ProductRepository) {}

  reserve(lines: readonly OrderLine[]): void {
    const allocations = this.allocate(lines);
    for (const { product, quantity } of allocations) {
      if (!product.canReserve(quantity)) {
        throw new InsufficientStockError(product.id, quantity.value, product.available);
      }
    }
    this.apply(allocations, (product, quantity) => product.reserve(quantity));
  }

  release(lines: readonly OrderLine[]): void {
    this.apply(this.allocate(lines), (product, quantity) => product.release(quantity));
  }

  dispatch(lines: readonly OrderLine[]): void {
    this.apply(this.allocate(lines), (product, quantity) => product.dispatch(quantity));
  }

  /** Resolves products and merges lines that refer to the same product. */
  private allocate(lines: readonly OrderLine[]): Allocation[] {
    const byProduct = new Map<string, Allocation>();
    for (const line of lines) {
      const existing = byProduct.get(line.productId);
      if (existing) {
        existing.quantity = existing.quantity.add(line.quantity);
        continue;
      }
      const product = this.products.findById(line.productId);
      if (!product) {
        throw new UnknownProductError(line.productId);
      }
      byProduct.set(line.productId, { product, quantity: line.quantity });
    }
    return [...byProduct.values()];
  }

  private apply(allocations: Allocation[], movement: (product: Product, quantity: Quantity) => void): void {
    for (const { product, quantity } of allocations) {
      movement(product, quantity);
      this.products.save(product);
    }
  }
}

